        child: Column(
          spacing: AppSpacing.spacing16,
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            SizedBox(width: double.infinity, child: StatusBar(time: '5:00')),
            // Search Section
            SizedBox(width: double.infinity,
              child: Padding(padding: EdgeInsets.symmetric(horizontal: AppSpacing.spacing12),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    SizedBox(width: double.infinity, child: SearchBar(
                      placeholder: AppLocalizations.of(context)!.searchInYourLibrary,
                      iconSearch: AppIcons.search,
                      iconMic: AppIcons.mic,
                    )),
                  ],
                ),
              ),
            ),
            // Library Tabs
            SizedBox(width: double.infinity,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // Tabs Row
                  SizedBox(width: double.infinity,
                    child: Padding(padding: EdgeInsets.symmetric(horizontal: AppSpacing.spacing8),
                      child: Row(
                        children: [
                          PrimaryTabs(
                            firstTab: TabItem(label: AppLocalizations.of(context)!.music),
                            secondTab: TabItem(
                              selected: true,
                              label: AppLocalizations.of(context)!.podcastsCaps,
                            ),
                            onChange: (index) { switch (index) { case 0: navigate('library-music'); case 1: navigate('library-podcasts'); } },
                          ),
                          SizedBox(width: AppSpacing.spacing12),
                          IconButton(icon: AppIcons.settings),
                          IconButton(icon: AppIcons.help),
                        ],
                      ),
                    ),
                  ),
                  SizedBox(width: double.infinity, child: Divider()),
                ],
              ),
            ),
            // Filter Chips
            SizedBox(width: double.infinity,
              child: Padding(padding: EdgeInsets.symmetric(horizontal: AppSpacing.spacing16),
                child: Row(
                  spacing: AppSpacing.spacing8,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    FilterChip(selected: true, label: AppLocalizations.of(context)!.episodes),
                    FilterChip(label: AppLocalizations.of(context)!.shows),
                  ],
                ),
              ),
            ),
            // Shortcut Tiles
            SizedBox(width: double.infinity,
              child: Padding(padding: EdgeInsets.symmetric(horizontal: AppSpacing.spacing16),
                child: Row(
                  spacing: AppSpacing.spacing8,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Expanded(child: LibraryShortcutTile(
                      label: AppLocalizations.of(context)!.saved,
                      icon: AppIcons.bookmark,
                    )),
                    Expanded(child: LibraryShortcutTile(
                      color: LibraryShortcutTileColor.cyan,
                      label: AppLocalizations.of(context)!.downloads,
                      icon: AppIcons.cloudDownload,
                    )),
                    Expanded(child: LibraryShortcutTile(
                      color: LibraryShortcutTileColor.magenta,
                      label: AppLocalizations.of(context)!.yourNewPodcasts,
                      icon: AppIcons.podcasts,
                    )),
                  ],
                ),
              ),
            ),
            // Continue Playing Header
            SizedBox(width: double.infinity,
              child: Padding(padding: EdgeInsets.symmetric(horizontal: AppSpacing.spacing16),
                child: Column(
                  spacing: AppSpacing.spacing8,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    SizedBox(width: double.infinity, child: SectionHeader(
                      title: AppLocalizations.of(context)!.continuePlaying,
                      showMore: false,
                      showSupportingText: false,
                      supportingText: AppLocalizations.of(context)!.discoverMusicBasedOnYourRecent,
                    )),
                  ],
                ),
              ),
            ),
            // Episodes
            SizedBox(width: double.infinity,
              child: Padding(padding: EdgeInsets.symmetric(horizontal: AppSpacing.spacing16),
                child: Column(
                  spacing: AppSpacing.spacing16,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    SizedBox(width: double.infinity, child: PodcastEpisodeCard(
                      description: 'In this episode we talk the Brit awards, Zayn\'s new It\'s You music video, and our current feelings about the band',
                      timeLeft: AppLocalizations.of(context)!.t1H42MinLeft,
                      showDownload: true,
                      progressIndicator: ProgressIndicator(value: ProgressIndicatorValue.v10),
                      image: const AssetImage('assets/figma-img/I27-1018-10-397.png'),
                      title: 'Harry Potter and the One Direction - Episode 37 - It\'s You',
                      subtitle: 'Talk Direction: The 1D (& Harry Styles) Podcast',
                      titleLines: 2,
                      hideActiveTrack: true,
                    )),
                    SizedBox(width: double.infinity, child: PodcastEpisodeCard(
                      description: 'Thank you for listening!! See Privacy Policy at https://art19.com/privacy and California Privacy Notice',
                      timeLeft: AppLocalizations.of(context)!.t1H2MinLeft,
                      showDownload: false,
                      progressIndicator: ProgressIndicator(value: ProgressIndicatorValue.v10),
                      image: const AssetImage('assets/figma-img/I27-1050-10-397.png'),
                      title: 'Broccoli Guts Pt. 2 | PITM #149',
                      subtitle: 'PitM',
                      titleLines: 2,
                      hideActiveTrack: true,
                    )),
                    SizedBox(width: double.infinity, child: PodcastEpisodeCard(
                      description: 'We are GHR - America\'s Dance Music Mixshow! This weeks GHR is major! We are "LIVE" from COACHELLA',
                      timeLeft: AppLocalizations.of(context)!.t56MinLeft,
                      showDownload: true,
                      progressIndicator: ProgressIndicator(value: ProgressIndicatorValue.v40),
                      image: const AssetImage('assets/figma-img/I27-1072-10-397.png'),
                      title: 'GHR - Show 426 - LIVE from Coachella 2015 - Hour 2',
                      subtitle: 'Ghetto House Radio',
                      titleLines: 2,
                      hideActiveTrack: true,
                    )),
                  ],
                ),
              ),
            ),
            BottomNavigation(
              firstItem: NavigationItem(
                label: AppLocalizations.of(context)!.explore,
                icon: AppIcons.explore,
              ),
              secondItem: NavigationItem(label: AppLocalizations.of(context)!.search, icon: AppIcons.search),
              thirdItem: NavigationItem(
                label: AppLocalizations.of(context)!.connect,
                icon: AppIcons.groups,
              ),
              fourthItem: NavigationItem(
                selected: true,
                label: AppLocalizations.of(context)!.yourLibrary,
                icon: AppIcons.libraryMusic,
