              onChange: (index) { switch (index) { case 0: navigate('explore-viewport'); case 1: navigate('search-discover-viewport'); case 3: navigate('library-music'); } },
            ),
            MiniPlayer(
              image: const AssetImage('assets/figma-img/I27-1132-10-451.png'),
              title: 'لو كنت غالى',
              subtitle: 'مصطفى قمر',
              onOpen: () => navigate('now-playing'),
            ),
          ],
        ),
      ),
    );
